// Per gate: what one gate copies, decodes and builds at most (the rest waits
// for the next gate).
constexpr UINT64 kTransportBytes = 64ull << 20;
// The transport's fallback texture (transport_texture.hlsl): R32_UINT rows of 4096 words, 16 KB (a multiple of
// D3D12's 256-byte row pitch, so the rows copied back into a buffer are the words in their order).
constexpr UINT kTransportRowWords = 4096;
constexpr UINT64 kTransportRowBytes = kTransportRowWords * 4ull;
constexpr UINT64 kProbeBytes = 4096;  // the transport check's pattern (TransportCheck)
constexpr UINT64 kPositionsBytes = 96ull << 20;  // decoded float3 positions (8M vertices)
constexpr UINT64 kScratchBytes = 128ull << 20;   // BLAS build scratch
constexpr std::size_t kMaxMeshesPerGate = 256;
// Long-lived memory.
constexpr UINT64 kPageBytes = 256ull << 20;
constexpr std::uint32_t kMaxBlasPages = 16;
constexpr std::uint32_t kMaxRecords = kMaxGeometryRecords;
constexpr std::uint32_t kCubeStride = 64;     // MyVertexFormatCubeInstance
constexpr std::uint32_t kGenericStride = 32;  // MyVertexFormatGenericInstance
constexpr UINT64 kBlockAlignment = 64;
constexpr UINT64 kBlockBytes = 64ull << 20;
constexpr std::size_t kUploadSlots = 3;  // one per frame in flight (rt_core.cpp)
constexpr UINT64 kUploadBytesPerSlot = 32ull << 20;
constexpr std::uint32_t kInitialInstanceCapacity = 1u << 16;
constexpr UINT64 kAlignment = 256;
constexpr UINT kMaxDispatchGroups = 65535;
constexpr UINT64 kNoSpace = UINT64_MAX;
constexpr std::uint32_t kIndexBits = 24;
constexpr int kMaxLoggedFailures = 20;
// Half the light grid's width (lights.hlsli: kLightGridSize / 2 * kLightCellSize): lamps are traced
// for surface points within it.
constexpr float kLightGridReach = 32.0f;
// Skinned objects (characters): each posed into its own geometry in the skinned page, whose SRV is the last
// of the geometry pages' (the meshes' pages take the others).
constexpr UINT64 kSkinnedBytes = 64ull << 20;
constexpr std::uint32_t kSkinnedPage = kMaxGeometryPages - 1;
constexpr std::uint32_t kMaxMeshPages = kSkinnedPage;
constexpr std::uint32_t kSkinnedVertexBytes = 12;  // float3 positions; packed normal, tangent, texcoord
constexpr std::uint32_t kMinSkinnedStride = 20;    // MyVertexFormatPositionSkinning
constexpr UINT64 kSkinEvictFrames = 120;           // a pose no instance used for this long is released
// A pose's BLAS is refit to every new pose and built anew this often (the refit's boxes loosen as the
// animation departs from the pose it was built for), and after a frame without a pose.
constexpr UINT64 kSkinRebuildFrames = 60;
constexpr D3D12_RAYTRACING_ACCELERATION_STRUCTURE_BUILD_FLAGS kSkinBuildFlags =
    D3D12_RAYTRACING_ACCELERATION_STRUCTURE_BUILD_FLAG_ALLOW_UPDATE |
    D3D12_RAYTRACING_ACCELERATION_STRUCTURE_BUILD_FLAG_PREFER_FAST_TRACE;
