constexpr std::uint32_t kPreviousShift = 18;
constexpr UINT64 kPreviousUnit = 256;
constexpr UINT64 kMaxPreviousDistance = ((1ull << 14) - 1) * kPreviousUnit;

// Mirrors struct GeometryRecord in src/shaders/scene_common.hlsli: one per
// BLAS geometry; an instance's InstanceID is its mesh's first record, a hit's
// record is InstanceID + GeometryIndex.
struct GeometryRecord {
    std::uint32_t page;             // geometry page (ByteAddressBuffer index)
    std::uint32_t indexOffset;      // bytes: the part's first index
    std::uint32_t vertexOffset;     // bytes: VB0 vertex 0 of the part (base vertex applied)
    std::uint32_t attributeOffset;  // bytes: VB1 vertex 0 of the part, or 0xFFFFFFFF
    std::uint32_t layout;           // bits 0-7 VB0 stride, 8-15 VB1 stride, 16 32-bit indices, 17 float3 positions
    std::uint32_t material;         // index into the material table
    std::uint32_t flags;            // bits 0-7 part flags, 8-15 MeshKind
    std::uint32_t counts;           // bits 0-23 the part's triangles, 24-31 the mesh's records (at most 255;
                                    // emissive_lights.hlsl walks an instance's parts by it)
};
static_assert(sizeof(GeometryRecord) == 32);

