// First fit over free ranges kept by offset; frees merge with neighbours.
class RangeAllocator {
public:
    void Reset(const UINT64 size) {
        m_free.clear();
        m_free[0] = size;
        m_used = 0;
    }

    UINT64 Allocate(const UINT64 size, const UINT64 alignment) {
        for (auto it = m_free.begin(); it != m_free.end(); ++it) {
            const UINT64 blockStart = it->first;
            const UINT64 blockEnd = it->first + it->second;
            const UINT64 start = AlignUp(blockStart, alignment);
            if (start + size > blockEnd) {
                continue;
            }
            m_free.erase(it);
            if (start > blockStart) {
                m_free[blockStart] = start - blockStart;
            }
            if (start + size < blockEnd) {
                m_free[start + size] = blockEnd - (start + size);
            }
            m_used += size;
            return start;
        }
        return kNoSpace;
    }

    void Free(const UINT64 offset, const UINT64 size) {
        m_used -= size;
        UINT64 start = offset;
        UINT64 end = offset + size;
        auto next = m_free.lower_bound(offset);
        if (next != m_free.begin()) {
            auto previous = std::prev(next);
            if (previous->first + previous->second == start) {
                start = previous->first;
                m_free.erase(previous);
            }
        }
        if (next != m_free.end() && next->first == end) {
            end = next->first + next->second;
            m_free.erase(next);
        }
        m_free[start] = end - start;
    }

    [[nodiscard]] UINT64 Used() const {
        return m_used;
    }

private:
    std::map<UINT64, UINT64> m_free;
    UINT64 m_used = 0;
};

