// A skinned object's pose: its own geometry in the skinned page (the mesh's
// indices, 32-bit; posed float3 positions; those of the previous frame, for
// the animation's motion; packed normal, tangent and texcoord), its BLAS
// (built anew every frame it is posed) and its geometry records (written
// once: the geometry stays in place). Kept by the object's actor, mesh and
// place among the skins with both (as the placements).
struct Skin {
    bool ready = false;       // memory and records allocated
    UINT64 lastFrame = 0;     // PoseSkins' frame that last used it
    UINT64 posedFrame = 0;    // PoseSkins' frame that last posed it (0: never)
    UINT64 regionOffset = 0;  // bytes in the skinned page
    UINT64 regionBytes = 0;
    UINT64 positionRegion = 0;   // from regionOffset
    UINT64 previousRegion = 0;   // from regionOffset; 0: none (positions beyond the records' reach)
    UINT64 attributeRegion = 0;  // from regionOffset; 0: no attributes
    std::uint32_t vertexCount = 0;
    std::uint32_t blasPage = 0;
    UINT64 blasOffset = 0;
    UINT64 blasBytes = 0;
    UINT64 scratchBytes = 0;   // a build's or a refit's, whichever needs more
    UINT64 builtFrame = 0;     // PoseSkins' frame of the last full build (0: none yet)
    D3D12_GPU_VIRTUAL_ADDRESS blas = 0;
    std::uint32_t firstRecord = 0;
    std::uint32_t recordCount = 0;
    std::uint32_t triangles = 0;
};

